// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }
    function testFuzz_property(uint256 amount1, uint256 amount2, address actor) public {
        vm.assume(amount1 > 0 && amount2 > 0 && amount1 <= type(uint256).max / 2 && amount2 <= type(uint256).max / 2);
        vm.assume(actor != address(0) && actor != address(this));
        vm.deal(actor, amount1 + amount2);

        vm.prank(actor);
        c.deposit{value: amount1}();
        vm.prank(actor);
        c.withdrawAll();

        vm.prank(actor);
        c.deposit{value: amount2}();
        vm.prank(actor);
        c.withdrawAll();

        int256 balanceAfter = int256(address(c).balance);
        assertTrue(balanceAfter >= 0, "balance should never be negative");
    }
}
